--   3   Imran Hossain     01370850415  Dhaka        Style Point Mohammadpur          RETAIL      MR-74242
--   4   Farhana Akter     01986438563  Dhaka        ShopKoro Online                  ECOMMERCE   MR-76907
--   5   Mehedi Hasan      01331051863  Chattogram   Quick Fix Mobile Repair Agrabad  SERVICES    MR-72838
--   6   Sadia Chowdhury   01952724711  Chattogram   Biriyani Bari Halishahar         RESTAURANT  MR-76439
--   7   Kamrul Islam      01852441428  Gazipur      Shefa Pharmacy Tongi             PHARMACY    MR-70970
--   8   Shirin Sultana    01349448077  Gazipur      Shoe Palace Joydebpur            RETAIL      MR-77375
--   9   Habib Mollah      01548091044  Narayanganj  Green Basket Chashara            GROCERY     MR-75165
--   10  Anika Roy         01678419799  Narayanganj  Book Corner Siddhirganj          OTHER       MR-79736
--
-- • The only new accounts are these 10 merchants. Every payer is one of the
--   5 existing personal customers (Ashraful Islam, Arif Sheikh, Rahim Haque,
--   Karim Begum, Rakib Uddin), each only after their own sign-up date.
-- • 3520 transactions: add money successful 897, merchant payment successful 2205, settlement successful 343, merchant payment refunded 17, refund successful 31, merchant payment failed 27.
-- • Patterns: weekly rhythm, Ramadan / Eid / Pohela Boishakh peaks, an
--   11.11 online sale, a fast-growing online shop (ShopKoro Online) and two
--   merchants declining over the last 30 days (Biriyani Bari Halishahar,
--   Book Corner Siddhirganj). Merchants settle 80% to their bank weekly.
-- • Fees follow src/services/mock/policy.ts (customer pays 1.5% on top).
-- • Customers' purchases are funded by Add Money top-ups inside this file,
--   so their wallets only go up by what is left over; merchant wallets end
--   at what they had not yet settled to the bank.
-- • Ids start with syn_mx_ (scripts/seed-synthetic.mjs --reset removes them).
-- Amounts are in paisa (100 = ৳1).
-- ════════════════════════════════════════════════════════════════════

begin;

do $$
begin
  if exists (select 1 from users where id like 'syn\_mx\_%') then
    raise exception 'The new merchants are already there — this script only runs once.';
  end if;
  if (select count(*) from wallets where user_id in ('usr_ashraful', 'syn_usr_000011', 'syn_usr_000015', 'syn_usr_000019', 'syn_usr_00001d')) <> 5 then
    raise exception 'Some customers are missing: run seed.sql and synthetic-data.sql first.';
  end if;
  if exists (select 1 from users where phone in ('01817582633', '01900613319', '01370850415', '01986438563', '01331051863', '01952724711', '01852441428', '01349448077', '01548091044', '01678419799')
                                   or email in ('syn.merchant5@example.com', 'syn.merchant6@example.com', 'syn.merchant7@example.com', 'syn.merchant8@example.com', 'syn.merchant9@example.com', 'syn.merchant10@example.com', 'syn.merchant11@example.com', 'syn.merchant12@example.com', 'syn.merchant13@example.com', 'syn.merchant14@example.com'))
     or exists (select 1 from merchant_businesses where merchant_id in ('MR-72620', 'MR-74740', 'MR-74242', 'MR-76907', 'MR-72838', 'MR-76439', 'MR-70970', 'MR-77375', 'MR-75165', 'MR-79736')) then
    raise exception 'A phone, email or merchant id below is already used by another account — nothing was changed.';
  end if;
end $$;

-- Customers must exist before their first purchase here.
update users set created_at = '2025-07-01 04:00:00+00', updated_at = greatest(updated_at, '2025-07-01 04:00:00+00')
 where id = 'usr_ashraful' and created_at > '2025-07-01 04:00:00+00';

-- users (10)

-- merchant_profiles (10)

-- merchant_businesses (10)

-- account_status_history (20)

-- wallets (10) — start empty; the history's effect is added below

-- transactions 2025-10 (171)

-- transactions 2025-11 (205)

-- transactions 2025-12 (290)

-- transactions 2026-01 (280)

-- transactions 2026-02 (248)

-- transactions 2026-03 (331)

-- transactions 2026-04 (286)

-- transactions 2026-05 (336)

-- transactions 2026-06 (301)

-- transactions 2026-07 (355)

-- transactions 2026-08 (360)

-- transactions 2026-09 (284)

-- transactions 2026-10 (73)

-- This history's effect on every wallet (same rules as the app's ledger).
with eff as (
  select e.user_id, sum(e.avail)::bigint avail, count(*) n, max(t.created_at) last_at
  from transactions t
  cross join lateral (values
    (t.sender_user_id,   -(t.amount + t.sender_fee)),
    (t.receiver_user_id, t.amount - t.receiver_fee)
  ) e(user_id, avail)
  where t.id like 'syn\_mx\_%' and t.status in ('SUCCESSFUL', 'REFUNDED') and e.user_id is not null
  group by e.user_id
)
update wallets w
   set available = w.available + eff.avail,
       version = w.version + eff.n::int,
       updated_at = case when w.user_id like 'syn\_mx\_%' then eff.last_at else now() end
  from eff
 where w.user_id = eff.user_id;

do $$
begin
  if (select count(*) from transactions where id like 'syn\_mx\_%') <> 3520 then
    raise exception 'Row count mismatch — nothing was changed.';
  end if;
  if exists (select 1 from wallets where available < 0) then
    raise exception 'A balance would go negative — nothing was changed.';
  end if;
end $$;

commit;

-- Result: the new merchants, their year of sales and current balance.
select b.business_name, b.merchant_id, b.district, b.category, u.phone,
       count(t.id) filter (where t.type = 'MERCHANT_PAYMENT' and t.status <> 'FAILED') as sales,
       (sum(t.amount) filter (where t.type = 'MERCHANT_PAYMENT' and t.status <> 'FAILED') / 100.0)::numeric(14,2) as sales_taka,
       (w.available / 100.0)::numeric(14,2) as balance_taka
from merchant_businesses b
join users u on u.id = b.user_id
join wallets w on w.user_id = b.user_id
left join transactions t on t.receiver_user_id = b.user_id
where b.user_id like 'syn\_mx\_%'
group by b.business_name, b.merchant_id, b.district, b.category, u.phone, w.available
order by b.district, b.business_name;
